mapper.insert:
INSERT INTO attendance_event (company_id, attendance_id, attendance_device_id, event_type, received_at, event_key)
SELECT a.company_id, a.attendance_id, #{attendanceDeviceId}, #{eventType},
       CASE WHEN #{eventType} = 'ATT_IN' THEN a.check_in_at ELSE a.check_out_at END,
       #{eventKey}
FROM attendance a
WHERE a.attendance_id = #{attendanceId} AND a.company_id = #{companyId}

